Let $\Omega=\Omega^+\subset {\mathbb R}^2$ be a Jordan domain, let $\Omega^-={\mathbb R}^2\setminus \overline{\Omega^+}$, and let $\Gamma=
    \partial\Omega^+$.  Then, up to a set of zero ${\mathcal H}^1$-measure,
  \begin{equation}\label{eqCar00}
    \mbox{$\displaystyle {\mathcal E}_\Omega(x)^2:=\int_0^1 {\varepsilon}_\Omega(x,r)^2\,\frac{dr}r<\infty$\; for $x\in\Gamma$ \quad$\Leftrightarrow$ \quad
      $\Omega$ has a tangent at $x\in\Gamma$.}
  \end{equation}
  In particular, the set
  $G=\{x\in\Gamma:{\mathcal E}(x)<\infty\}$ is $1$-rectifiable.

Let $\Omega^+$ and $\Omega^-$ be two disjoint open subsets of ${\mathbb R}^{n+1}$. Suppose that $\mu$ is an $n$-Ahlfors regular measure with $\operatorname{supp}(\mu) = \partial \Omega^+ \cup \partial \Omega^-$. Then the following are equivalent.
  \begin{enumerate}
    \item $\Omega^+$ and $\Omega^-$ are complementary two-sided corkscrew open sets, and in particular $\mu$ is uniformly $n$-rectifiable.
    \item There is a constant $C_1$ so that for each ball $B$ centered on $\operatorname{supp}(\mu)$ it holds that
          \begin{equation*} 
            \int_B \int_0^{r(B)} {\varepsilon}_{n,\Omega^\pm} (x,r)^2 \, \tfrac{dr}{r} \, d\mu(x) \leq C_1 r(B)^n.
          \end{equation*}
  \end{enumerate}

Let $\Omega=\Omega^+\subset {\mathbb R}^2$ be a Jordan domain, let $\Omega^-={\mathbb R}^2\setminus \overline{\Omega^+}$, and let $\Gamma=
    \partial\Omega^+$.
  Let $\alpha>0$ and suppose that there exists some constant $C>0$ such that
  \begin{equation}\label{eqhyp91}
    {\varepsilon}_\Omega(x,r)\leq C\,r^{\alpha}\quad \mbox{ for all $x\in\Gamma$ and all $0<r\leq {\rm diam}(\Gamma)$.}
  \end{equation}
  Then $\Omega$ is a $C^{1,\beta}$ domain, for some $\beta>0$ depending only on $\alpha$.

\label{teomain}
  Let $\Omega\subset{\mathbb R}^{n+1}$ be a bounded open set with $n$-Ahlfors regular boundary and let $0<\alpha<1$. Then $\Omega$ is a $C^{1,\alpha}$ open set
  if and only if there exists some constant $C$ such that
  \begin{equation}\label{eqhyp92}
    {\varepsilon}_{n,\Omega}(x,r)\leq C\,r^{\alpha}\quad \mbox{ for all $x\in{\partial\Omega}$ and all $0<r\leq {\rm diam}({\partial\Omega})$.}
  \end{equation}

For $n\geq1$, let $\Omega^+, \Omega^-\subset{\mathbb R}^{n+1}$ be open and disjoint. For fixed $\alpha>0$ and $r_0>0$, suppose that there
  exists a constant $C>0$ such that
  \begin{equation}\label{eqCar00*}
    \alpha_{\Omega^\pm}(x,r)\leq C\,r^{2\alpha}\quad \mbox{ for all $x\in{\partial\Omega}^+\cup {\partial\Omega}^-$ and all $0<r\leq r_0$.}
  \end{equation}
  Then ${\partial\Omega}^+={\partial\Omega}^-$ is a $C^{1,\beta}$ manifold, with $\beta>0$ depending on $\alpha$.

\label{lem:second-difference}
  Let $f\colon I\to\mathbb{R}$ be continuous and $0<\alpha\leq1$. Suppose
  \begin{equation}\label{eq:criterion-hypothesis}
    |\delta_h^2f(z)|\leq M|h|^{1+\alpha}
    \quad\text{whenever }z-h,z+h\in I.
  \end{equation}
  Then $f\in C^1(I)$ and
  \begin{equation}\label{eq:holder-constant}
    |f'(x)-f'(y)|\leq\frac{M}{2^\alpha-1}|x-y|^\alpha
    \qquad\forall x,y\in I.
  \end{equation}

\label{thm:planar-interval}
  Let $0<\alpha\leq1$ and let $f\colon (-1,1)\to\mathbb{R}$ be $L$-Lipschitz, with
  $L<1$. Suppose
  \[
    {\widetilde{{\varepsilon}}}_f(z,r)\leq C_{\varepsilon} r^\alpha
    \quad\text{for all }z\in(-1,1)\text{ and }r>0\text{ with }[z-r,z+r]\subset(-1,1).
  \]
  Then $f\in C^{1,\alpha}((-1/4,1/4))$, and
  \begin{equation}\label{eq:local-final-bound}
    [f']_{C^{0,\alpha}((-1/4,1/4))}
    \leq \frac{(1+L)(1+L^2)^{(1+\alpha)/2}}{2^\alpha-1}C_{\varepsilon}.
  \end{equation}

\label{thm:a-eta-decay}
  Let $x_0\in{\mathbb R}^n$ and $x=\varphi_g(x_0)$.
  If ${\widetilde{{\varepsilon}}}_g(x_0,t) \lesssim t^\alpha$ for all $t>0$, then
  \begin{align*}
    a_{\rho,\Omega_g^+}(x,r) \lesssim cr^\alpha.
  \end{align*}

\label{thm:LP-equals-a-rho}
  Let $g\colon\mathbb{R}^n\to\mathbb{R}$ satisfy a Lipschitz condition at $x_0$.
  Then,
  \begin{align*}
    |\xi_r \ast g (x_0)| = r \,a_{\eta,\Omega_g^+}(\varphi_g(x_0), r).
  \end{align*}

\label{thm:difference-of-a-coeff}
  Let $g\colon\mathbb{R}^n\to\mathbb{R}$ satisfy a Lipschitz condition at $x_0$.
  For any $N\in\mathbb{N}$ large enough, we have
  \begin{align*}
    \left|  a_{\eta,\Omega_g^+}(\varphi_g(x_0),r) - a_{\rho,\Omega_g^+}(\varphi_g(x_0),r)  \right|
    \lesssim_N L^2 \sum_{j\ge 1} \mathfrak b_g(x_0,2^jr) 2^{-Nj}.
  \end{align*}

\label{thm:LP-beta-general}
  Let $g\colon\mathbb{R}^n\to\mathbb{R}$ satisfy a Lipschitz condition at $x_0$.
  Then, for any sufficiently large $N\in\mathbb N$,
  \begin{align*}
    |\xi_r \ast g(x_0)|
     & \lesssim ra_{\rho,\Omega_g^+}(\varphi_g(x_0),r) + L^2 r \sum_{h\ge 1} \mathfrak b_g(x_0,2^h r) 2^{-Nh}.
  \end{align*}

\label{thm:LP-beta-estimate}
  Let $g\colon\mathbb{R}^n\to\mathbb{R}$ satisfy a Lipschitz condition at $x_0$,
  and let ${\widetilde{{\varepsilon}}}_g(x_0,t) \lesssim t^\alpha$ for all $t>0$.
  Then, for any sufficiently large $N\in\mathbb N$,
  \begin{align*}
    |\xi_r \ast g(x_0)|
     & \lesssim r^{1+\alpha} + L^2 r \sum_{h\ge 1} \mathfrak b_g(x_0,2^h r) 2^{-Nh}.
  \end{align*}

\label{thm:lipschitz-at-x0-suffices}
  It suffices to require that there exists $r_0>0$ such that ${\widetilde{{\varepsilon}}}_g(x_0,r)\le C_\varepsilon r^\alpha$ for $r\in (0,r_0)$.
  Since ${\widetilde{{\varepsilon}}}_g(x_0,\cdot)$ is uniformly bounded, we have
  \begin{align*}
    {\widetilde{{\varepsilon}}}_g(x_0,r)\lesssim (C_\varepsilon + r_0^{-\alpha}) r^\alpha, \quad\forall r>0.
  \end{align*}

\label{thm:beta-graph-product}
  Let $f,g\colon\mathbb{R}^n\to \mathbb{R}$.
  We have
  \begin{align*}
    |g(x_0)| \mathfrak b_f(x_0,r)
    \le \mathfrak b_{fg}(x_0,r) & +  |f(x_0)|  \mathfrak b_g(x_0,r)
    +  \sup_{y_0\in B(x_0,r)} \frac{|f(x_0) - f(y_0)| |g(x_0) - g(y_0)|}r.
  \end{align*}

If $g(x_0) \neq 0$, consider the affine function $A\colon\mathbb{R}^n\to\mathbb{R}$ defined by
  \begin{align*}
    A(y_0) := \frac{L_{fg}(y_0) - f(x_0) L_g(y_0) + f(x_0) g(x_0)}{g(x_0)},
  \end{align*}
  where $L_{fg}$ and $L_g$ are the minimizers of $\mathfrak b_{fg}(x_0,r)$ and $\mathfrak b_{g}(x_0,r)$, respectively.
  We calculate
  \begin{align*}
    g(x_0) (f(y_0) - A(y_0))
    = ( f(y_0)g(y_0) - L_{fg}(y_0) )
     & + f(x_0) ( L_g(y_0)-g(y_0) )          \\
     & - (f(x_0) - f(y_0))(g(x_0) - g(y_0)).
  \end{align*}
  Dividing by $r$, taking absolute values and $\sup_{y_0\in B(x_0,r)}$ yields the claim.

\label{thm:beta-graph-product*}
  Let $f,g\colon\mathbb{R}^n\to \mathbb{R}$.
  We have
  \begin{align*}
    \mathfrak b_{fg}(x_0,r) \le  |g(x_0)| \mathfrak b_f(x_0,r) & + |f(x_0)| \mathfrak b_g(x_0,r)
    + \sup_{y_0\in B(x_0,r)} \frac{|f(x_0) - f(y_0)| |g(x_0) - g(y_0)|}r.
  \end{align*}

Consider the affine function $A\colon\mathbb{R}^n\to\mathbb{R}$ defined by
  \begin{align*}
    A(y_0) = g(x_0) L_f(y_0)  + f(x_0) L_g(y_0) - f(x_0) g(x_0),
  \end{align*}
  where $L_f$ and $L_g$ are the minimizers of $\mathfrak b_{f}(x_0,r)$ and $\mathfrak b_{g}(x_0,r)$, respectively.
  Then we have
  \begin{align*}
    f(y_0)g(y_0) - A(y_0) =
    g(x_0) (f(y_0)- L_f(y_0)) & + f(x_0) (g(y_0) - L_g(y_0))          \\
                              & + (f(y_0) - f(x_0))(g(y_0) - g(x_0)).
  \end{align*}
  Dividing by $r$, taking absolute values and $\sup_{y_0\in B(x_0,r)}$ yields the lemma.

\label{thm:Aj-upper-bound-bk}
  Assume that ${\widetilde{{\varepsilon}}}_f(x_0,r)\lesssim r^\alpha$.
  We have
  \begin{align*}
    \left|  P_j u(x_0)  \right| \lesssim 2^{-(1+\alpha)j} + L^2 2^{-j} \sum_{h\ge 1} 2^{-Nh} \mathfrak{b}_u(x_0, 2^{h-j}), \qquad j\in\mathbb{Z}, \, x_0\in\mathbb{R}^n.
  \end{align*}

First, we have
  \begin{align}
    \left|  S_M u (z) - u(z)  \right|
    \le \int |\varphi_{2^{-M}}(w)| |u(z-w) - u(z) | \,\mathrm{d} w
    \le \lVert u \rVert_{\mathrm{Lip}} \int |\varphi_{2^{-M}}(w)| |w| \,\mathrm{d} w
    \lesssim 2^{-M},
  \end{align}
  so $\lVert S_M u - u \rVert_{\infty} \to 0$ as $M\to \infty$.
  Similarly,
  \begin{align*}
    \lVert P_j u  \rVert_{\infty} \le \lVert u \rVert_{\mathrm{Lip}} \int |\xi_{2^{-j}}(w)||w| \,\mathrm{d} w \lesssim 2^{-j}.
  \end{align*}
  Together, this implies the first claim.

  Next, we have
  \begin{align*}
    \nabla^2 S_k u = \nabla^2 S_M u + \sum_{M<j\le k} \nabla^2 P_j u, \quad M<k.
  \end{align*}
  Young's convolution inequality implies
  \begin{align*}
    \lVert  \nabla^2 S_M u  \rVert_{\infty}
    \le \lVert  \nabla^2 \varphi_{2^{-M}}  \rVert_{1} \lVert u \rVert_{\infty}
    \le 2^{2M} \lVert \nabla^2 \varphi \rVert_1 \lVert u \rVert_{\infty}
    \to 0,
  \end{align*}
  as $M\to -\infty$.

  Now \cite[Corollary 2.2.4]{grafakosModernFourierAnalysis2014} implies
  \begin{align*}
    \lVert \nabla^2 P_j u \rVert_{\infty} \lesssim 2^{2j} \lVert P_j u \rVert_{\infty}.
  \end{align*}
  Therefore,
  \begin{align*}
    \lVert \nabla^2 S_k u \rVert_{\infty} \lesssim \sum_{j\le k} 2^{2j} \lVert P_j u \rVert_{\infty}.
  \end{align*}

\label{thm:bk-upper-bound-Aj}
  Let $u\in C_c(\mathbb{R}^n)$ be Lipschitz.
  We have
  \begin{align*}
    \mathfrak b_k \lesssim \sum_j 2^{-|j-k|} A_j, \qquad\forall k\in\mathbb{Z}.
  \end{align*}

For $z\in\mathbb{R}^n$, define
  \begin{align*}
    a_{z,k}(w) := S_ku(z) + \nabla S_k u(z) \cdot (w-z).
  \end{align*}
  From the representation in the lemma above, we have
  \begin{align*}
    \sup_{w\in B(z,r)} |u(w) - a_{z,k}(w)|
     & \le \frac{1}{2} r^2 \lVert  \nabla^2 S_k u \rVert_{\infty} + \sum_{j>k} \lVert P_j u \rVert_{\infty}      \\
     & \lesssim r^2 \sum_{j\le k} 2^{2j} \lVert P_j u \rVert_{\infty} + \sum_{j>k} \lVert P_j u \rVert_{\infty}.
  \end{align*}
  Setting $r=2^{-k}$, dividing by $r$ and taking $\sup_z$ yields the conclusion.

\label{l:A}
  Suppose $K$ is large enough. Then
  the function $A: L_0 \to L_0^\perp$ is supported in $KB_{Q_0}\cap L_0$ and is Lipschitz with slope $\lesssim \lambda_0$ in $10B_{Q_0}$. Moreover, if $i\in I_{0}$, then for any $x \in 15 S_i$,
  \begin{align*}
    |\nabla^2A(x)| \lesssim \frac{\epsilon}{\ell_1}.
  \end{align*}

\label{l:distQ-L}
  For $Q\in {\rm Tree}({\widetilde{Q}}_0)$ such that $Q\cap 10B_{Q_0}\neq\varnothing$ and $x\in \Gamma\cap 3B_Q$, it holds that
  \begin{align}\label{e:distQ-L}
    {\rm dist}(x,L_Q) \lesssim \epsilon \ell(Q).
  \end{align}

\label{l:distG-A}
  We have    \begin{align*}
    {\rm dist}(x, \Gamma) \lesssim \epsilon \ell_1\quad\text{for every }x\in {\partial\Omega}\cap 10B_{Q_0}.
  \end{align*}

\label{l:LBcloseGA}
  For $Q\in {\rm Tree}({\widetilde{Q}}_0)$  such that $Q\cap 10B_{Q_0}\neq\varnothing$, it holds that
  \begin{align}
    {\rm dist}(x, \Gamma)\lesssim \epsilon \ell(Q) \quad \text{for all }x\in L_Q\cap 2B_Q.
  \end{align}

\label{coroGamma}
  For every $x\in\Gamma\cap 6B_{Q_0}$, we have
  \begin{equation}\label{eqbbetaG1}
    b\beta_\Gamma(x,r)\lesssim \epsilon\quad \mbox{ for all $r>0$,}
  \end{equation}
  and
  \begin{equation}\label{eqbbetaG2}
    b\beta_\Gamma(x,r)\lesssim \epsilon\,\frac r\ell_1\quad \mbox{ for all $r\leq\ell_1$.}
  \end{equation}

\label{lembkfac}
  The following holds:
  \begin{itemize}
    \item[(a)] $\mathfrak b_k \lesssim \epsilon$ for all $k\in{\mathbb Z}$.

    \item[(b)] $\mathfrak b_k \lesssim \epsilon 2^{-(k-k_1)}$ for all $k\geq k_1$.
  \end{itemize}

\label{lembkloop}
  We have
  \begin{equation}\label{eqsumk*}
    \sum_{k\geq k_0} \sum_{j\geq k_0} 2^{-|j-k|} \sum_{h\ge 1}2^{-Nh} \mathfrak b_{j-h}  \lesssim \sum_{j=k_0}^{k_1} \mathfrak b_j + \epsilon.
  \end{equation}

\label{lemafc991}
  For all $x\in 5B_{Q_0}\cap\Gamma$ the following holds:
  \begin{itemize}
    \item[(a)] $a_{\rho,\Omega_A^+}(x,r)\lesssim \epsilon$ for all $r>0$.

    \item[(b)] $a_{\rho,\Omega_A^+}(x,r)\lesssim \epsilon\,\dfrac{r}{\ell_1}$ for all $0<r\leq \ell_1$.
  \end{itemize}

\label{lemdifarho}
  Given $x\in 5B_{Q_0}\cap\Gamma$, let $x'\in{\partial\Omega}$ be such that $|x-x'|\lesssim\epsilon\ell_1$. For all $r\in[\ell_1,\ell(Q_0)]$,
  we have
  \begin{align}\label{eqx2}
    \big| a_{\rho,\Omega_A^+}(x,r) - a_{\rho,\Omega_A^+}(x',r)\big|\lesssim \frac{\epsilon \ell_1}r.
  \end{align}

Write $A_{x,j}=A(x,2^j r,2^{j+1}r)$ for $j >0$ and $A_{x,0} = B(x,2r)$. Write also $A_{j}=A(0,2^{j-1},2^{j+2})$ for $j >0$ and $A_{0} = B(0,4)$.
  Using that $|x-x'|\leq \epsilon \ell_1\ll r$, it follows that
  $$\frac{|x-z|}r \in A_{j}  \quad \mbox{ if $z\in A_{x,j}$.}$$
  Then we get
  \begin{align*}
    \big|a_{\rho,\Omega_A^+} (x,r) - a_{\rho,\Omega_A^+} (x',r)\big| & \leq \frac1{r^{n+1}}\int_{\Omega_A^+}
    \bigg| \psi\biggl(\frac{|x-y|}{r}\biggr) - \psi\bigg(\frac{|x'-y|}{r}\bigg)\bigg|\,{\mathrm{d}} y                                                      \\
                                                                     & \leq \sum_{j\geq0} \frac1{r^{n+1}}\int_{A_{x,j}} \sup_{z\in A_{x,j}}
    \bigg| \psi\biggl(\frac{|x-z|}{r}\biggr) - \psi\bigg(\frac{|x'-z|}{r}\bigg)\bigg|\,{\mathrm{d}} y                                                      \\
                                                                     & \lesssim \sum_{j\geq0} \sup_{\xi\in A_j}|\nabla \psi(\xi)|\,\frac{|x-x'|}r
    \lesssim \frac{\epsilon\ell_1}r.
  \end{align*}

\label{lemmaguai*}
  For all $x\in 5B_{Q_0}\cap\Gamma$ and all $r\in[\ell_1,\ell(Q_0)]$,  we have
  $$a_{\rho,\Omega_A^+}(x,r) \lesssim r^\alpha + \epsilon\,\frac r{\ell(Q_0)} +  \epsilon\,\frac{\ell_1}r.$$
